PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE jobs (
            slug         TEXT PRIMARY KEY,
            file_path    TEXT NOT NULL,
            category     TEXT,
            cbeta_id     TEXT,
            juan_index   INTEGER DEFAULT 0,
            status       TEXT NOT NULL DEFAULT 'pending',
            backend      TEXT,
            model        TEXT,
            agent_id     TEXT,
            priority     INTEGER DEFAULT 0,
            seg_total    INTEGER DEFAULT 0,
            seg_done     INTEGER DEFAULT 0,
            created_at   TEXT,
            started_at   TEXT,
            updated_at   TEXT,
            completed_at TEXT,
            error        TEXT
        , locked_backend TEXT, locked_model TEXT, locked_agent_id TEXT, full_model TEXT);
CREATE INDEX idx_status ON jobs(status, priority DESC);
COMMIT;
